package cn.huankan.collector;
import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/bls") public class BlsController {private final BlsCollector service;public BlsController(BlsCollector s){service=s;}public record Request(List<String> series,int startYear,int endYear){}@PostMapping("/status")public Object status(){return service.status();}@PostMapping("/collect")public Object collect(@RequestBody Request r){return service.collect(r.series(),r.startYear(),r.endYear());}@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class,org.springframework.dao.DataAccessException.class})public org.springframework.http.ResponseEntity<?> invalid(){return org.springframework.http.ResponseEntity.badRequest().body(Map.of("message","BLS配置、许可或请求预算未通过；未执行额外请求"));}}
